// Vendor original photos (owner request 2026-11-17: add the original picture to all listings).
// m7-m17 already carry their originals. This patch adds them to m18, m20-m27 at the END of each gallery
// (per colour where the listing has colours). m19 was skipped at first: the seller's frames have the
// wholesale price text burned in. On 2026-11-20 the owner asked for the writing to be removed, so the
// Cream / Mint Green / Black originals below are cleaned copies (price text, captions and app icons
// removed, print unchanged). The Red colour was removed from m19 on 2026-11-20 at owner instruction.
var VENDOR_ORIGINALS = {"append":{"m20":["data:image/webp;base64,","data:image/webp;base64,"],"m21":["data:image/webp;base64,","data:image/webp;base64,"],"m22":["data:image/webp;base64,"],"m23":["data:image/webp;base64,","data:image/webp;base64,"],"m24":["data:image/webp;base64,","data:image/webp;base64,"],"m27":["data:image/webp;base64,","data:image/webp;base64,"]},"perColour":{"m18":{"Black":["data:image/webp;base64,"],"Yellow":["data:image/webp;base64,"],"Sky Blue":["data:image/webp;base64,"],"White":["data:image/webp;base64,"]},"m25":{"Black":["data:image/webp;base64,","data:image/webp;base64,"],"Mint Green":["data:image/webp;base64,","data:image/webp;base64,"]},"m26":{"Yellow":["data:image/webp;base64,","data:image/webp;base64,"],"Black":["data:image/webp;base64,","data:image/webp;base64,"]},"m19":{"Cream":["data:image/jpeg;base64,"],"Mint Green":["data:image/jpeg;base64,"],"Black":["data:image/jpeg;base64,"]}}};
(function () {
  function byId(id) { for (var i = 0; i < PRODUCTS.length; i++) if (PRODUCTS[i].id === id) return PRODUCTS[i]; return null; }
  var app = VENDOR_ORIGINALS.append;
  for (var id in app) {
    var p = byId(id); if (!p) continue;
    p.gallery = (p.gallery || []).concat(app[id]);
  }
  var pc = VENDOR_ORIGINALS.perColour;
  for (var pid in pc) {
    var prod = byId(pid); if (!prod || !prod.colourShots) continue;
    var cs = prod.colourShots;
    var photos = [prod.image].concat(prod.gallery || []);
    var n = prod.colours.length;
    var tail = photos.slice(n * cs);
    var all = [];
    var add = 0;
    for (var ci = 0; ci < n; ci++) {
      var block = photos.slice(ci * cs, (ci + 1) * cs);
      var extra = pc[pid][prod.colours[ci]] || [];
      add = extra.length;
      all = all.concat(block).concat(extra);
    }
    all = all.concat(tail);
    prod.colourShots = cs + add;
    prod.image = all[0];
    prod.gallery = all.slice(1);
  }
})();
